<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Domain;use Acorn\SafetyHealthcheck\Content\RecommendationRepository;use InvalidArgumentException;
final class ResultsEngine{public function __construct(private ?RecommendationRepository $recommendations=null){$this->recommendations??=new RecommendationRepository;}public function evaluate(array $questions,array $answers,string $jurisdiction,int $version):array{$find=[];foreach($questions as $q){$k=$q['question_key'];if(!isset($answers[$k]))continue;$a=AnswerValue::assert($answers[$k]);if($a==='yes'){$status='addressed';$rec=null;}else{$rec=$this->recommendations->resolve($version,$k,$a,$jurisdiction);if(!$rec)throw new InvalidArgumentException('Recommendation unavailable.');$status=$rec['finding_status'];}$find[]=['question_key'=>$k,'module_key'=>$q['module_key'],'answer_value'=>$a,'finding_status'=>$status,'recommendation'=>$rec,'question'=>$q];}return$this->rollUp($find);}public function rollUp(array $find):array{$sections=[];$rank=['not_assessed'=>0,'addressed'=>1,'review'=>2,'priority'=>3];foreach($find as $f){$m=$f['module_key'];if(!isset($sections[$m])||$rank[$f['finding_status']]>$rank[$sections[$m]])$sections[$m]=$f['finding_status'];}$counts=array_count_values(array_column($find,'finding_status'));$p=$counts['priority']??0;$r=$counts['review']??0;return['findings'=>$find,'section_statuses'=>$sections,'priority_count'=>$p,'review_count'=>$r,'addressed_count'=>$counts['addressed']??0,'overall_status'=>OverallStatus::fromCounts($p,$r)];}}
